function mobileCommand(command){
 flushMobileEdits();
 if(!['menu','levels','view-options','element-more'].includes(command)&&$('#modal').open)$('#modal').close();
 if(command==='apply'){closeDrawers();render();return;}
 if(command==='plan'){closeDrawers();u.tool='pan';u.mobilePanel='add';renderPlan();return;}
 if(command==='elements'){closeDrawers();u.mobilePanel='browse';u.mobileFind='';u.tool='pan';renderCatalog();$('.app').classList.add('show-catalog');}
 if(command==='add'){u.mobilePanel='add';u.step='layout';u.query='';u.selected=null;u.tool='pan';render();$('.app').classList.remove('show-inspector');$('.app').classList.add('show-catalog');}
 if(command==='hub'){u.mobilePanel='hub';u.selected=null;renderCatalog();$('.app').classList.remove('show-inspector');$('.app').classList.add('show-catalog');}
 if(command==='building'||command==='comfort'||command==='budget'){u.mobilePanel=command;go(command);}
 if(command==='levels'){closeDrawers();openModal('Mes niveaux',levelPicker(s,compute(s),u.levelId));}
 if(command==='level-settings'){u.mobilePanel='level';go('building');}
 if(command==='report'){u.selected=null;u.inspector='overview';renderInspector();$('.app').classList.remove('show-catalog');$('.app').classList.add('show-inspector');}
 if(command==='technical')showTechnical();
 if(command==='menu')openModal('Mon projet',moreMenu());
 if(command==='rename')renameDialog();
 if(command==='help')guide();
 if(command==='dimensions'||command==='position'){if(!current())return;u.tool='pan';u.mobileResize=false;u.mobileEditTab=command==='position'?'position':'dimensions';u.inspector='selection';renderInspector();$('.app').classList.remove('show-catalog');$('.app').classList.add('show-inspector');}
 if(command==='move'){if(!current())return;closeDrawers();u.view='plan';u.mobileResize=false;u.tool=u.tool==='select'?'pan':'select';renderPlan();if(u.tool==='select')mobileFocus();}
 if(command==='nudge-step'){const steps=[.1,.5,1];u.mobileNudge=steps[(steps.indexOf(u.mobileNudge)+1)%steps.length];renderSelectionBar();}
 if(command==='resize'){if(!current())return;closeDrawers();u.view='plan';u.tool='select';u.mobileResize=true;renderPlan();}
 if(command==='cancel-mode'){if(drag&&drag.before){s=JSON.parse(drag.before);drag=null;}u.draft=null;u.mobileResize=false;u.tool='pan';renderPlan();}
 if(command==='deselect'){u.selected=null;u.tool='pan';renderPlan();}
 if(command==='focus')mobileFocus();
 if(command==='expand')$('.app').classList.toggle('sheet-expanded');
 if(command==='element-more'){openModal(esc(selectedName()),`<div class="m-menu-list"><button data-mobile="position"><span class="m-menu-icon">${icon('cursor')}</span><span><strong>Position précise</strong><small>Coordonnées et emplacement</small></span></button>${!['opening','platform'].includes(u.selected.type)?`<button data-action="rotate"><span class="m-menu-icon">${icon('rotate')}</span><span><strong>Tourner de 90°</strong></span></button>`:''}${u.selected.type!=='opening'?`<button data-mobile="resize"><span class="m-menu-icon">${icon('ruler')}</span><span><strong>Redimensionner au doigt</strong></span></button>`:''}${u.selected.type!=='platform'?`<button data-action="duplicate"><span class="m-menu-icon">${icon('copy')}</span><span><strong>Dupliquer</strong></span></button><button data-action="delete"><span class="m-menu-icon">${icon('trash')}</span><span><strong>Retirer cet élément</strong><small>Annulation possible</small></span></button>`:`<button data-mobile="level-settings"><span class="m-menu-icon">${icon('layers')}</span><span><strong>Réglages du plancher</strong></span></button>`}</div>`);}
 if(command==='view-options')openModal('Affichage du plan',`<div class="m-view-options"><button data-mobile="toggle-grid" class="${u.grid?'active':''}">Grille de 1 m ${u.grid?icon('check'):icon('grid')}</button><button data-mobile="toggle-snap" class="${u.snap?'active':''}">Aimantation de 10 cm ${u.snap?icon('check'):icon('magnet')}</button>${[['layout','Aménagement'],['light','Lumière & vitrage'],['thermal','Isolation'],['ceiling','Plafonds']].map(([k,t])=>`<button data-mobile-layer="${k}" class="${u.layer===k?'active':''}">${t}${u.layer===k?icon('check'):icon('layers')}</button>`).join('')}<button data-mobile="fit">Tout le bâtiment${icon('fit')}</button><button data-mobile="fullscreen">${$('.app').classList.contains('fullscreen')?'Réduire le plan':'Plan en plein écran'}${icon('expand')}</button></div><p>Glissez pour parcourir le plan. À deux doigts, pincez pour zoomer.</p>`);
 if(command==='toggle-grid'){u.grid=!u.grid;renderPlan();mobileCommand('view-options');return;}
 if(command==='toggle-snap'){u.snap=!u.snap;renderPlan();mobileCommand('view-options');return;}
 if(command==='fit'){renderPlan(true);}if(command==='fullscreen'){$('.app').classList.toggle('fullscreen');}
 renderMobileShell();
}
function setupMobile(){
 const setViewport=()=>{const v=window.visualViewport,h=v?.height||innerHeight,inset=Math.max(0,innerHeight-h-(v?.offsetTop||0));document.documentElement.style.setProperty('--m-vh',Math.round(h)+'px');document.documentElement.style.setProperty('--m-keyboard',Math.round(inset)+'px');document.documentElement.classList.toggle('m-keyboard-open',inset>80);};
 setViewport();window.visualViewport?.addEventListener('resize',setViewport);window.addEventListener('resize',setViewport);
 mobileMedia.addEventListener('change',()=>{flushMobileEdits(false);u.tool=isMobile()?'pan':'select';u.mobilePanel='add';$('.app').classList.remove('show-catalog','show-inspector','sheet-expanded');render(true);});
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushMobileEdits(false);});
 document.addEventListener('focusin',e=>{if(isMobile()&&e.target.matches('input,select')&&e.target.closest('.catalog,.inspector')){$('.app').classList.add('sheet-expanded');requestAnimationFrame(()=>e.target.scrollIntoView({block:'nearest',inline:'nearest'}));}});
 let grip=null;document.addEventListener('pointerdown',e=>{if(isMobile()&&e.target.closest('[data-sheet-grip]')){grip={id:e.pointerId,y:e.clientY,node:e.target.closest('[data-sheet-grip]')};grip.node.setPointerCapture(e.pointerId);}});
 document.addEventListener('pointerup',e=>{if(!grip||grip.id!==e.pointerId)return;const dy=e.clientY-grip.y;if(dy>55)closeDrawers();else if(dy<-25)$('.app').classList.add('sheet-expanded');grip=null;});
}

let confirmation=null;
function confirmAction(title,body,fn){confirmation=fn;openModal(title,`<p>${body}</p><div class="modal-actions"><button class="btn" data-modal-close>Conserver</button><button class="btn primary" data-confirm>Continuer</button></div>`);}
function freeSpot(w,l,obstacles,preferred=null){if(preferred){const p={x:clamp(snap(preferred.x),0,s.building.w-w),y:clamp(snap(preferred.y),0,s.building.l-l)};if(!obstacles.some(r=>overlap({...p,w,l},r)))return p;}for(let y=0;y<=s.building.l-l+.01;y+=.25)for(let x=0;x<=s.building.w-w+.01;x+=.25)if(!obstacles.some(r=>overlap({x,y,w,l},r)))return{x,y};return{x:Math.max(0,(s.building.w-w)/2),y:Math.max(0,(s.building.l-l)/2)};}
function surfaceDialog(kind){
 const k=SURFACE_TYPES[kind];if(!k)return;const choices=s.levels.filter(l=>kind==='terrace'||l.elevation>0),target=choices.find(l=>l.id===u.levelId)?.id||choices[0]?.id||'new',newAllowed=s.levels.length<8;
 if(!choices.length&&!newAllowed){toast('Créez ou utilisez un niveau supérieur.');return;}
 const elevation=activeLevel().elevation+Math.max(activeLevel().height,...s.rooms.filter(r=>r.levelId===u.levelId).map(r=>r.h))+.2;
 openModal('Ajouter une '+k.name.toLowerCase(),`<p>Une surface ouverte, indépendante des pièces et de la surface habitable.</p><div class="fields one"><label class="field"><span>Nom</span><input id="surface-name" value="${k.name}" maxlength="50"></label><label class="field"><span>Niveau de la surface</span><select id="surface-level">${choices.map(l=>`<option value="${l.id}" ${target===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}${newAllowed?`<option value="new" ${target==='new'?'selected':''}>Nouveau niveau en hauteur</option>`:''}</select></label></div><div class="fields">${localField('Largeur','surface-width',Math.min(k.w,s.building.w),'m','.1',.6,s.building.w*2)}${localField('Longueur','surface-length',Math.min(k.l,s.building.l),'m','.1',.6,s.building.l*2)}</div><div id="surface-altitude" ${target!=='new'?'hidden':''}>${localField('Altitude du nouveau niveau','surface-elevation',Math.round(elevation*100)/100,'m','.1',.3,30)}</div><p class="subtle-text">Vous pourrez déplacer, redimensionner et dupliquer cette surface sur le plan.</p><div class="modal-actions"><button class="btn" data-modal-close>Fermer</button><button class="btn primary" data-create-surface data-kind="${kind}">Créer la surface</button></div>`);
}
function createSurface(){
 const kind=$('[data-create-surface]').dataset.kind,k=SURFACE_TYPES[kind],newLevel=$('#surface-level').value==='new',levelId=newLevel?uid():$('#surface-level').value,id=uid(),name=$('#surface-name').value.trim()||k.name,w=Number($('#surface-width').value),l=Number($('#surface-length').value),elevation=Number($('#surface-elevation').value);
 action(()=>{if(newLevel)s.levels.push({id:levelId,name:kind==='mezzanine'?'Mezzanine '+s.levels.length:'Étage '+s.levels.length,kind:kind==='mezzanine'?'mezzanine':'floor',elevation,height:2.4,thickness:.2,platform:null});const space=s.rooms.filter(q=>q.levelId===levelId).concat(s.surfaces.filter(q=>q.levelId===levelId)),spot=freeSpot(Math.min(w,s.building.w),Math.min(l,s.building.l),space);s.surfaces.push({id,kind,name,levelId,w,l,...spot,railing:true,finish:'wood'});u.levelId=levelId;u.selected={type:'surface',id};u.tool=isMobile()?'pan':'select';u.allLevels=true;},true);
 $('#modal').close();closeDrawers();choose('surface',id);toast(k.name+' créée · placez-la librement');
}
function addRoom(kind,pos=null,dimensions=null){const k=ROOM_TYPES[kind];if(!k)return;const w=Math.min(dimensions?.w||k.w,s.building.w),l=Math.min(dimensions?.l||k.l,s.building.l),obstacles=s.rooms.filter(r=>r.levelId===u.levelId),spot=dimensions?{x:dimensions.x,y:dimensions.y}:pos?{x:clamp(snap(pos.x-w/2),0,s.building.w-w),y:clamp(snap(pos.y-l/2),0,s.building.l-l)}:freeSpot(w,l,obstacles,activeLevel().platform);const id=uid();action(()=>s.rooms.push({id,type:kind,name:k.name,levelId:u.levelId,h:activeLevel().height,...spot,w,l,lux:k.lux}));choose('room',id);closeDrawers();toast('Pièce créée · la surface habitable se recalcule');}
function beginDrawing(){flushMobileEdits();u.tool='draw';u.view='plan';u.drawType=current()&&u.selected.type==='room'?current().type:'other';u.selected=null;closeDrawers();renderInspector();renderPlan();toast('Tirez un rectangle sur le plan pour créer la pièce');}
function addObject(kind,pos=null){if(kind==='stairs'){addStairs();return;}const k=OBJECTS[kind];if(!k)return;const rooms=s.rooms.filter(r=>r.levelId===u.levelId);let r=null;if(!k.shop){if(u.selected?.type==='room')r=current();else if(u.selected?.type==='object')r=rooms.find(r=>r.id===current().roomId);r=r||rooms.find(r=>r.type===({bed:'bed',wardrobe:'bed',kitchen:'kitchen',island:'kitchen',fridge:'kitchen',shower:'bath',wc:'bath',sink:'bath',desk:'office'}[kind]||'living'))||rooms[0];}if(pos)r=rooms.find(r=>pos.x>=r.x&&pos.x<=r.x+r.w&&pos.y>=r.y&&pos.y<=r.y+r.l);if(k.group==='pool')r=null;
const parent=r||s.building;
const basin=!pos&&k.group==='pool'&&kind!=='pool'
 ? s.objects.filter(o=>o.kind==='pool'&&objectLevel(s,o)===u.levelId).at(-1)
 : null;
const rotatePool=kind==='pool'?parent.l<k.l&&parent.w>parent.l:!!basin&&(['poolLadder','poolCover'].includes(kind))&&basin.w>basin.l;
const w=kind==='ceiling'&&r?r.w:Math.min(rotatePool?k.l:k.w,parent.w);
const l=kind==='ceiling'&&r?r.l:Math.min(rotatePool?k.w:k.l,parent.l);
let spot=null;
if(basin&&['poolLadder','poolCover'].includes(kind)){
 const pool=objectRect(s,basin),horizontal=pool.w>pool.l,ladder=kind==='poolLadder';
 spot=horizontal
  ? {x:pool.x+pool.w-(ladder?w*.65:w),y:pool.y+(pool.l-l)/2}
  : {x:pool.x+(pool.w-w)/2,y:pool.y-(ladder?l*.35:0)};
}else if(pos)spot={x:clamp(snap(pos.x-(r?.x||0)-w/2),0,parent.w-w),y:clamp(snap(pos.y-(r?.y||0)-l/2),0,parent.l-l)};else if(kind==='ceiling'&&r){spot={x:0,y:0};}else if(k.group==='ceiling'&&r){spot={x:(r.w-w)/2,y:(r.l-l)/2};}else if(k.group==='ceiling'){spot={x:(parent.w-w)/2,y:(parent.l-l)/2};}else if(r){for(let y=.1;y<=r.l-l+.01&&!spot;y+=.2)for(let x=.1;x<=r.w-w+.01;x+=.2)if(!s.objects.filter(o=>o.roomId===r.id).some(o=>overlap({x,y,w,l},o))){spot={x,y};break;}}else spot=freeSpot(w,l,[...rooms,...s.objects.filter(o=>!o.roomId&&objectLevel(s,o)===u.levelId)]);spot=spot||{x:Math.max(0,(parent.w-w)/2),y:Math.max(0,(parent.l-l)/2)};const id=uid();action(()=>s.objects.push({id,kind,roomId:r?.id||null,levelId:u.levelId,...spot,w,l,rotation:rotatePool?90:0,price:k.price}));if(k.group){u.view='plan';u.layer=k.group==='ceiling'?'ceiling':'layout';}choose('object',id);closeDrawers();toast(`${k.name} ajouté(e)`);}

function addOpening(kind){const room=u.selected?.type==='room'?current():null,id=uid(),w=kind==='window'?1.2:kind==='door'?.9:3,h=kind==='window'?1.2:kind==='door'?2.1:3;const o={id,kind,host:room?'room':'building',roomId:room?.id||null,levelId:u.levelId,wall:kind==='bay'?'east':'north',offset:0,w,h,sill:kind==='window'?.9:0};let spot=null;for(const wall of (kind==='bay'?['east','south','north','west']:['north','west','south','east'])){const p=room||s.building,len=['north','south'].includes(wall)?p.w:p.l;for(let offset=.2;offset<=len-w-.1;offset+=.1){const a=openingSegment(s,{...o,wall,offset}),test={x:Math.min(a.x1,a.x2)-.05,y:Math.min(a.y1,a.y2)-.05,w:Math.abs(a.x2-a.x1)+.1,l:Math.abs(a.y2-a.y1)+.1};if(!s.openings.filter(q=>openingLevel(s,q)===u.levelId).some(q=>{const b=openingSegment(s,q);return overlap(test,{x:Math.min(b.x1,b.x2)-.05,y:Math.min(b.y1,b.y2)-.05,w:Math.abs(b.x2-b.x1)+.1,l:Math.abs(b.y2-b.y1)+.1});})){spot={wall,offset};break;}}if(spot)break;}action(()=>s.openings.push({...o,...spot}));choose('opening',id,true);toast('Ouverture ajoutée sur '+activeLevel().name);}

function rotate(){const o=current();if(!o||u.selected.type==='opening'||u.selected.type==='platform')return;action(()=>{const w=o.w;o.w=o.l;o.l=w;if(u.selected.type==='object')o.rotation=((o.rotation||0)+90)%360;});}
function duplicate(){const o=current();if(!o||u.selected.type==='platform')return;const copy=structuredClone(o),type=u.selected.type;copy.id=uid();if(type==='opening')copy.offset+=copy.w+.15;else{copy.x+=.3;copy.y+=.3;if(type==='room'||type==='surface')copy.name+=' (copie)';}action(()=>{(type==='room'?s.rooms:type==='surface'?s.surfaces:type==='object'?s.objects:s.openings).push(copy);});choose(type,copy.id);toast('Élément dupliqué');}
function remove(){const o=current();if(!o||u.selected.type==='platform')return;const type=u.selected.type,removeNow=()=>{action(()=>{if(type==='room'){for(const q of s.objects.filter(q=>q.roomId===o.id)){const p=objectRect(s,q);q.x=p.x;q.y=p.y;q.roomId=null;q.levelId=o.levelId;}s.openings=s.openings.filter(q=>q.roomId!==o.id);s.rooms=s.rooms.filter(q=>q.id!==o.id);}else if(type==='surface')s.surfaces=s.surfaces.filter(q=>q.id!==o.id);else if(type==='object')s.objects=s.objects.filter(q=>q.id!==o.id);else s.openings=s.openings.filter(q=>q.id!==o.id);u.selected=null;});toast('Élément retiré · annuler pour le restaurer');};if(type==='room')confirmAction('Retirer cette pièce ?',`Retirer « ${esc(o.name)} » ? Son mobilier restera en place et ses ouvertures attachées seront retirées.`,removeNow);else removeNow();}

function zoom(factor,event=null){if(u.view==='volume'&&volumeView){volumeView.zoom(factor);return;}let before=event?point(event):null;u.zoom=clamp(u.zoom*factor,.5,isMobile()?6:5);applyViewBox();if(before){const after=point(event);u.panX+=before.x-after.x;u.panY+=before.y-after.y;applyViewBox();}}
function showPopover(anchor,html){const p=$('#popover');p.innerHTML=html;p.hidden=false;const r=anchor.getBoundingClientRect();p.style.left=`${Math.max(8,Math.min(innerWidth-220,r.right-210))}px`;p.style.top=`${Math.min(innerHeight-p.offsetHeight-12,r.bottom+8)}px`;}
function exportMenu(){showPopover($('#export-button'),`<button data-export="json">${icon('file')}<span>Projet modifiable<small>JSON · plan seul</small></span></button><button data-export="archive">${icon('folder')}Plan et versions (JSON)</button><button data-action="versions">${icon('layers')}Versions du plan</button><button data-export="svg">${icon('plan')}<span>Plan du niveau actif<small>SVG · net à toutes les tailles</small></span></button><button data-export="png">${icon('eye')}<span>Image du niveau actif<small>PNG · partager votre idée</small></span></button><hr><button data-action="print">${icon('file')}<span>Récapitulatif imprimable<small>Plan, quantités & budget · PDF via imprimer</small></span></button><hr><button data-action="import">${icon('folder')}Importer un projet JSON</button><button data-action="projects">${icon('folder')}Mes projets sur cet appareil</button>`);}
const filename=()=>s.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'atelier-habitat';
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function svgExport(){const bounds=planBounds(s,u.levelId);return `<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="${Math.round(1800*bounds.h/bounds.w)}" viewBox="${bounds.x} ${bounds.y} ${bounds.w} ${bounds.h}"><rect x="${bounds.x}" y="${bounds.y}" width="${bounds.w}" height="${bounds.h}" fill="#f3f4ec"/>${plan2D(s,{...u,layer:'layout',grid:false,selected:null},true)}</svg>`;}
async function exportFile(type){$('#popover').hidden=true;if($('#modal').open)$('#modal').close();if(type==='png'&&u.view==='volume'&&volumeView){toast('Préparation de l’image 3D…');try{const blob=await volumeView.imageBlob();if(blob){download(blob,filename()+'-vue-3d.png');toast('Vue 3D exportée');}else toast('Export impossible. Réessayez en vue 2D.');}catch(error){console.warn('Export 3D :',error);toast('Export impossible. Réessayez en vue 2D.');}return;}if(type==='archive'){save();download(new Blob([JSON.stringify(packPlan(s,u.levelId,projects[activeId].versions),null,2)],{type:'application/json'}),filename()+'-versions.json');toast('Plan et versions exportés');}else if(type==='json'){download(new Blob([JSON.stringify({...s,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),filename()+'.json');toast('Projet exporté');}else if(type==='svg'){download(new Blob([svgExport()],{type:'image/svg+xml;charset=utf-8'}),filename()+'-'+activeLevel().name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-')+'.svg');toast('Plan vectoriel exporté');}else if(type==='png'){const url=URL.createObjectURL(new Blob([svgExport()],{type:'image/svg+xml'})),im=new Image();im.onload=()=>{const canvas=document.createElement('canvas');canvas.width=im.naturalWidth;canvas.height=im.naturalHeight;canvas.getContext('2d').drawImage(im,0,0);canvas.toBlob(b=>{if(b){download(b,filename()+'-'+activeLevel().name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-')+'.png');toast('Image du plan exportée');}else toast('Export impossible. Essayez le format SVG.');});URL.revokeObjectURL(url);};im.onerror=()=>{URL.revokeObjectURL(url);toast('Export impossible. Essayez le format SVG.');};im.src=url;}}
function printProject(){closeDrawers();$('#popover').hidden=true;const view=u.view;u.view='plan';renderPlan(true);requestAnimationFrame(()=>{window.print();u.view=view;renderPlan(true);});}
function projectsDialog(){save();openModal('Mes plans',`<div class="tech-actions"><button class="btn" data-action="versions">Versions du plan ouvert</button><button class="btn" data-action="import">Importer un plan</button><button class="btn" data-export="archive">Exporter avec les versions</button></div>${Object.entries(projects).map(([id,p])=>`<div class="project-row"><button data-project-load="${esc(id)}"><strong>${esc(p.data.name)}</strong><small>${fmt(area(p.data.building))} m² · ${fmt(compute(normalize(p.data)).home)} m² habités ${id===activeId?'· projet ouvert':''}</small></button>${id!==activeId?`<button class="icon-btn" data-project-delete="${esc(id)}" title="Supprimer ce projet" aria-label="Supprimer ${esc(p.data.name)}">${icon('trash')}</button>`:'<span class="mini-tag">OUVERT</span>'}</div>`).join('')}<div class="modal-actions"><button class="btn" data-project-new="copy">${icon('copy')}Créer une variante</button><button class="btn primary" data-project-new="new">${icon('plus')}Nouveau projet</button></div>`);}
function switchProject(id){if(!projects[id])return;s=normalize(projects[id].data);activeId=id;u.techPlacement=null;u.levelId=projects[id]?.levelId||'ground';u.selected=null;past=[];future=[];save();render(true);$('#modal').close();closeDrawers();toast('Projet ouvert');}
function newProject(copy=false){save();s=copy?structuredClone(s):defaults();if(!copy){const kind=$('#new-building-kind')?.value||'warehouse';
 const [w,l,h]=({warehouse:[15,10,5.5],house:[10,9,2.7],apartment:[8,7,2.5],other:[10,10,3]})[kind];
 Object.assign(s.building,{kind,w,l,h,price:0});s.levels[0].height=Math.min(2.6,h);
 s.rooms=[];s.surfaces=[];s.objects=[];s.openings=[];u.step='layout';u.category='rooms';}s.name=copy?s.name+' — variante':'Nouveau projet';activeId=uid();u.techPlacement=null;u.levelId='ground';u.selected=null;past=[];future=[];save();render(true);$('#modal').close();closeDrawers();renameDialog();}
function renameDialog(){openModal('Donnez un nom à votre lieu',`<label class="field"><span>Nom du projet</span><input id="rename-value" type="text" maxlength="70" value="${esc(s.name)}" autocomplete="off"></label><div class="modal-actions"><button class="btn" data-modal-close>Fermer</button><button class="btn primary" data-rename>Enregistrer</button></div>`);$('#rename-value').focus();$('#rename-value').select();}
function methods(){const C=compute(s);openModal('Des calculs lisibles, un projet à affiner',`<div class="info-note" style="margin-top:0"><div><strong>Outil d’avant-projet</strong>Les résultats servent à comparer vos idées. Les prix sont des hypothèses modifiables, sans tarif fournisseur en direct. Le plan utilise des surfaces brutes : l’épaisseur des murs et cloisons n’est pas retranchée.</div></div><h3>Isolation & quantités</h3><p>R = épaisseur en mètres / conductivité λ. Les surfaces d’ouverture sont retirées des murs. Les pièces définissent leur enveloppe, y compris les parois vers l’atelier. Les murs communs et les planchers entre pièces chauffées ne sont pas ajoutés à l’isolation. La marge de coupe est appliquée aux achats et au prix des matériaux, pas aux surfaces géométriques.</p><table class="method-table"><tr><th>Surface</th><th>Nette</th><th>Avec marge ${fmt(s.thermal.waste)} %</th></tr>${[['Murs',C.walls],['Plafond',C.roof],['Sol',C.floor]].map(([t,a])=>`<tr><td>${t}</td><td>${fmt(a)} m²</td><td>${fmt(a*(1+s.thermal.waste/100))} m²</td></tr>`).join('')}</table><h3>Thermique</h3><p>Déperditions = Σ(surface × U × écart de température), auxquelles s’ajoute le renouvellement d’air : 0,34 × volume × débit en vol/h × ΔT. U = 1 / (R isolant + résistance superficielle simplifiée). Les fenêtres et les portes ont leur propre U. L’atelier, l’extérieur et le sol peuvent avoir des températures différentes. Ponts thermiques, structure existante, apports solaires et infiltrations additionnelles ne sont pas modélisés. Ce n’est ni un DPE, ni une étude réglementaire, ni un calcul de puissance de chauffage.</p><h3>Lumière naturelle & artificielle</h3><p>Le pourcentage de vitrage est un objectif de conception réglable, initialement 16,7 %. Il ne valide aucune conformité. Seule la partie de fenêtre donnant réellement sur une façade de la pièce est prise en compte. Pas de simulation d’exposition, d’ombrage ni de transmission lumineuse. Le nord affiché est un repère visuel.</p><p>Luminaires = arrondi supérieur de (surface × lux / lumens / facteur d’utilisation). Les points dessinés illustrent la quantité calculée. Les lux sont des hypothèses par usage, ajustables par pièce. L’atelier au rez-de-chaussée et les planchers ouverts à l’étage utilisent l’éclairement de l’atelier. Les consommations supposent tous les luminaires allumés simultanément pendant ${fmt(s.light.hours)} h/jour.</p><h3>Pièces, étages et mezzanines</h3><p>Les surfaces Mezzanine et Terrasse s’ajoutent depuis le catalogue Surfaces, indépendamment des pièces. Elles ne sont pas comptées comme habitation. Une terrasse peut dépasser l’emprise du bâtiment ; seule sa partie intérieure occupe le sol de l’atelier. Le coût des terrasses au sol est une hypothèse séparée, réglable dans Budget. La surface habitable est l’union des pièces de chaque niveau, cumulée entre niveaux. Un étage ne soustrait pas de surface libre au rez-de-chaussée. L’escalier réserve son emprise sur son niveau de départ et crée une trémie sur son niveau d’arrivée ; cette trémie est retirée des surfaces de plancher. Un plancher ouvert n’est pas une pièce habitable. Les hauteurs sont paramétrables ; les collisions verticales sont signalées. Les portées, charges, ancrages et sections de structure ne sont pas dimensionnés par cet outil.</p><h3>Budget</h3><p>Acquisition + frais + isolants + parois + planchers ajoutés et garde-corps + forfait réseaux/finitions + menuiseries + mobilier + imprévus sur les travaux. Le coût d’un meuble peut être modifié en le sélectionnant. Les cloisons partagées sont comptées une seule fois. Hors étude de structure, réfection du bâtiment, raccordements extérieurs, taxes et démarches. Les provisions n’incluent pas un devis de main-d’œuvre spécifique.</p>${warnings(C).length?`<h3>À ajuster sur ce plan</h3><ul>${warnings(C).map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}<div class="modal-actions"><button class="btn primary" data-modal-close>Revenir au projet</button></div>`);}
function guide(){if(isMobile()){openModal('Les gestes du studio',`<h3>1. Ajouter</h3><p>Le bouton Ajouter propose les pièces, le mobilier et les ouvertures. Dessinez aussi une pièce en tirant un rectangle sur le plan.</p><h3>2. Sélectionner et régler</h3><p>Touchez un élément, puis Dimensions. Les boutons + et − ajustent ses cotes. Terminer enregistre les réglages et ramène au plan.</p><h3>3. Se déplacer</h3><p>Glissez pour parcourir le plan. Pincez à deux doigts pour zoomer, ou utilisez + et −. Une pièce sélectionnée se déplace avec le bouton Déplacer ; les glissements habituels ne la bougent pas.</p><h3>4. Étages et projet</h3><p>Touchez le nom du niveau en haut du plan pour changer d’étage ou créer une mezzanine. Projet regroupe le bâtiment, le confort et le budget. Le menu en haut donne accès aux sauvegardes et exports.</p><p>Les changements sont enregistrés sur cet appareil. Exportez le projet en JSON pour le conserver ou le transférer.</p><div class="modal-actions"><button class="btn" data-action="methods">Calculs & hypothèses</button><button class="btn primary" data-modal-close>C’est parti</button></div>`);return;}openModal('Quelques gestes, beaucoup de possibilités',`<h3>1. Définissez le bâtiment</h3><p>Réglez la largeur, la longueur et la hauteur. Placez vos pièces directement dans le bâtiment : elles définissent la surface du logement. Ajoutez un niveau pour installer une habitation à l’étage ou une mezzanine. Trois scénarios permettent de repartir rapidement.</p><h3>2. Dessinez votre quotidien</h3><p>Dessinez un rectangle avec le bouton « Dessiner une pièce », ou ajoutez une pièce du catalogue. Placez-la où vous voulez, puis ajoutez le mobilier. Touchez un élément pour le sélectionner ; glissez-le pour le déplacer. Le carré dans l’angle permet de changer ses dimensions. Le bouton règle ouvre des cotes précises. Sur mobile, « Ajouter & configurer » ouvre le catalogue.</p><h3>3. Explorez les volumes</h3><p>Passez en vue en volume et glissez pour faire tourner le bâtiment. L’édition de position se fait en 2D. Les parois sont volontairement coupées pour voir l’intérieur. La barre des niveaux permet de passer du RDC aux étages. En volume, « Isoler » n’affiche que le niveau actif et « Éclaté » écarte les étages.</p><h3>4. Ajustez le confort et les coûts</h3><p>Placez les ouvertures, testez l’isolation et les points lumineux, puis adaptez les coûts à vos devis. Les alertes en bas du plan signalent les chevauchements et votre objectif de vitrage.</p><h3>Vos raccourcis</h3><div class="keyboard-grid"><span>Sélection / déplacer la vue</span><span><kbd>V</kbd> <kbd>H</kbd></span><span>Annuler / rétablir</span><span><kbd>Ctrl Z</kbd> <kbd>Ctrl Maj Z</kbd></span><span>Tourner / dupliquer</span><span><kbd>R</kbd> <kbd>Ctrl D</kbd></span><span>Déplacer de 10 cm</span><kbd>Flèches</kbd><span>Supprimer / désélectionner</span><span><kbd>Suppr</kbd> <kbd>Échap</kbd></span><span>Zoomer / recentrer</span><span>Molette · <kbd>0</kbd></span></div><h3>Enregistrer et partager</h3><p>Les projets sont enregistrés dans ce navigateur, sur cet appareil. « Exporter » permet de récupérer le projet modifiable en JSON, un plan SVG ou PNG et un récapitulatif imprimable. Les fichiers JSON du premier configurateur restent importables.</p><div class="modal-actions"><button class="btn" data-action="methods">Calculs & hypothèses</button><button class="btn primary" data-modal-close>C’est parti</button></div>`);}

function localField(label,id,value,unit='',step='.1',min=0,max=30){return field(label,'@local',unit,step,min,max,value).replace('data-entity-field="local"',`id="${id}"`);}
function newLevelDialog(){if(s.levels.length>=8){toast('Vous avez déjà 8 niveaux.');return;}const from=activeLevel(),z=from.elevation+Math.max(from.height,...s.rooms.filter(r=>r.levelId===from.id).map(r=>r.h))+.2;if(isMobile()){mobileNewLevel(from,z);return;}openModal('Ajouter un étage ou une mezzanine',`<p>Le niveau est indépendant. Chaque pièce y crée automatiquement son plancher.</p><div class="fields"><label class="field"><span>Type de niveau</span><select id="new-level-kind"><option value="floor">Étage habitable</option><option value="mezzanine">Mezzanine avec plancher ouvert</option></select></label><label class="field"><span>Nom</span><input id="new-level-name" value="Étage ${s.levels.length}" maxlength="45"></label>${localField('Altitude du sol fini','new-level-z',Math.round(z*100)/100,'m')}${localField('Hauteur sous plafond','new-level-height',2.4,'m','.1',1,15)}${localField('Épaisseur du plancher','new-level-thickness',.2,'m','.05',.05,1)}<label class="field"><span>Aménagement de départ</span><select id="new-level-mode"><option value="empty">Niveau vide</option><option value="copy">Copier les pièces de ${esc(from.name)}</option><option value="move">Déplacer les pièces de ${esc(from.name)}</option></select></label></div><div id="new-level-platform-fields" hidden><h3>Plancher ouvert de la mezzanine</h3><div class="fields">${localField('Largeur','new-level-w',Math.min(6,s.building.w),'m','.1',.6,s.building.w)}${localField('Longueur','new-level-l',Math.min(4,s.building.l),'m','.1',.6,s.building.l)}</div></div><p class="subtle-text">Les pièces copiées ou déplacées prennent la hauteur du nouveau niveau. Les conflits avec la toiture ou le niveau inférieur sont signalés sur le plan.</p><div class="modal-actions"><button class="btn" data-modal-close>Fermer</button><button class="btn primary" data-create-level>Créer le niveau</button></div>`);}
function createLevel(){const kind=$('#new-level-kind').value,id=uid(),from=u.levelId,height=Number($('#new-level-height').value),mode=$('#new-level-mode').value,rooms=s.rooms.filter(r=>r.levelId===from),elevation=Number($('#new-level-z').value),thickness=Number($('#new-level-thickness').value),name=$('#new-level-name').value.trim()||(kind==='mezzanine'?'Mezzanine':'Étage '+s.levels.length),platform=kind==='mezzanine'?{x:0,y:0,w:Number($('#new-level-w').value),l:Number($('#new-level-l').value)}:null;
const movingOpenings=s.openings.filter(o=>openingLevel(s,o)===from&&(rooms.some(r=>r.id===o.roomId)||o.kind==='window'&&rooms.some(r=>segmentOnRect(openingSegment(s,o),r)>.01)));
action(()=>{s.levels.push({id,kind,name,elevation,height,thickness,platform});if(mode==='move'){for(const r of rooms){r.levelId=id;r.h=height;}for(const o of s.objects.filter(o=>rooms.some(r=>r.id===o.roomId)))o.levelId=id;for(const o of movingOpenings)o.levelId=id;}if(mode==='copy'){const ids=new Map();for(const r of rooms){const copy={...r,id:uid(),levelId:id,h:height};ids.set(r.id,copy.id);s.rooms.push(copy);}for(const o of [...s.objects].filter(o=>ids.has(o.roomId)))s.objects.push({...o,id:uid(),roomId:ids.get(o.roomId),levelId:id});for(const o of movingOpenings)s.openings.push({...o,id:uid(),roomId:ids.get(o.roomId)||null,levelId:id});}u.levelId=id;u.selected=null;u.allLevels=true;},true);$('#modal').close();closeDrawers();toast(name+' créé · choisissez ou dessinez vos pièces');}
function removeLevel(){const l=activeLevel();if(l.kind==='ground')return;confirmAction('Retirer '+esc(l.name)+' ?',`Ce niveau, ses pièces, son mobilier et les escaliers associés seront retirés. Vous pourrez annuler cette action.`,()=>{action(()=>{const roomIds=new Set(s.rooms.filter(r=>r.levelId===l.id).map(r=>r.id));s.objects=s.objects.filter(o=>objectLevel(s,o)!==l.id&&o.targetLevelId!==l.id);s.openings=s.openings.filter(o=>openingLevel(s,o)!==l.id);s.rooms=s.rooms.filter(r=>!roomIds.has(r.id));s.surfaces=s.surfaces.filter(q=>q.levelId!==l.id);s.technical.points=s.technical.points.filter(p=>p.levelId!==l.id);delete s.technical.origins[l.id];s.levels=s.levels.filter(q=>q.id!==l.id);u.levelId=s.levels[0].id;u.selected=null;},true);toast('Niveau retiré · annuler pour le restaurer');});}
function addStairs(){const target=activeLevel().kind!=='ground'?activeLevel():[...s.levels].filter(l=>l.elevation>0).sort((a,b)=>a.elevation-b.elevation)[0];if(!target){toast('Créez d’abord un étage ou une mezzanine.');newLevelDialog();return;}const source=[...s.levels].filter(l=>l.elevation<target.elevation).sort((a,b)=>b.elevation-a.elevation)[0]||s.levels[0],p=target.platform||s.surfaces.find(q=>q.levelId===target.id)||s.rooms.find(r=>r.levelId===target.id),k=OBJECTS.stairs,id=uid(),w=k.w,l=k.l,spot=p?{x:clamp(snap(p.x+p.w-w-.15),0,s.building.w-w),y:clamp(snap(p.y+.1),0,s.building.l-l)}:freeSpot(w,l,s.rooms.filter(r=>r.levelId===source.id));action(()=>{s.objects.push({id,kind:'stairs',roomId:null,levelId:source.id,targetLevelId:target.id,...spot,w,l,rotation:0,price:k.price});u.levelId=target.id;});choose('object',id);closeDrawers();toast('Escalier ajouté · sa trémie suit son déplacement');}

function showTechnical(){
 closeDrawers();
 u.techNet||='electric';u.techPlacement=null;u.view='plan';u.layer='layout';u.selected=null;u.draft=null;u.tool='pan';
 renderPlan();
 openModal('Plan technique',technicalScreen(s,u.levelId,u.techNet,u.techTab));
}
function technicalPointDialog(id){
 const item=s.technical.points.find(p=>p.id===id),kind=item?.kind||Object.keys(POINTS).find(k=>POINTS[k].net.includes(u.techNet)),definition=POINTS[kind];
 const types=Object.entries(POINTS).filter(([,p])=>item||p.net.includes(u.techNet));
 const origin=networkOrigin(s,u.levelId,u.techNet);
 openModal(item?'Modifier le point':'Ajouter un point',`<label class="field"><span>Équipement</span><select id="tech-kind">${types.map(([k,p])=>`<option value="${k}" ${k===kind?'selected':''}>${p.name}</option>`).join('')}</select></label><label class="field"><span>Nom personnalisé</span><input id="tech-name" value="${esc(item?.name||'')}" maxlength="65" placeholder="Nom de l’équipement"></label><label class="field" id="tech-circuit-field" ${definition.circuit?'':'hidden'}><span>Circuit personnalisé</span><input id="tech-circuit" maxlength="50" value="${esc(item?.circuit||'')}" placeholder="Automatique"></label>${item?`<div class="fields">${localField('Position X','tech-x',item.x,'m','.01',0,s.building.w)}${localField('Position Y','tech-y',item.y,'m','.01',0,s.building.l)}</div>`:''}<label class="switch-row"><span>Aimanter au mur au placement</span><input id="tech-wall-snap" type="checkbox" ${['socket','switch','tap','ventilation'].includes(kind)?'checked':''}></label><div class="tech-actions"><button class="btn" data-tech-action="back">Retour aux réseaux</button><button class="btn primary" data-tech-place="${item?.id||'new'}">${item?'Déplacer sur le plan':'Placer sur le plan'}</button>${item?`<button class="btn" data-tech-save="${item.id}">Enregistrer</button>`:`<button class="btn" data-tech-save="new" data-x="${origin.x}" data-y="${origin.y}">Ajouter à l’origine</button>`}</div>${item?`<div class="tech-actions"><button class="btn" data-tech-via="${item.id}">Imposer un passage</button>${item.via[u.techNet]?`<button class="btn" data-tech-auto="${item.id}">Rétablir le tracé automatique</button>`:''}<button class="btn danger" data-tech-delete="${item.id}">Retirer le point</button></div>`:''}`);
}
function editedTechnicalPoint(id){
 const previous=s.technical.points.find(p=>p.id===id),kind=$('#tech-kind').value;
 return {...previous,id:previous?.id||uid(),levelId:u.levelId,kind,name:$('#tech-name').value.trim()||POINTS[kind].name,circuit:POINTS[kind].circuit?$('#tech-circuit').value:'',via:previous?.via||{}};
}
function storeTechnicalPoint(item,coordinates){
 action(()=>{
  const previous=s.technical.points.findIndex(p=>p.id===item.id);
  if(previous===-1)s.technical.points.push({...item,...coordinates});
  else s.technical.points[previous]={...item,...coordinates};
 });
}
function armTechnical(placement){
 u.techPlacement=placement;$('#modal').close();renderPlan();
}
function technicalCommand(t){
 if(t.dataset.techTab){u.techTab=t.dataset.techTab;showTechnical();return true;}
 if(t.dataset.techNet){u.techNet=t.dataset.techNet;showTechnical();return true;}
 if(t.dataset.techEdit){technicalPointDialog(t.dataset.techEdit);return true;}
 if(t.dataset.techPlace){armTechnical({mode:'point',point:editedTechnicalPoint(t.dataset.techPlace),wall:$('#tech-wall-snap').checked});return true;}
 if(t.dataset.techSave){
  const p=editedTechnicalPoint(t.dataset.techSave);
  storeTechnicalPoint(p,{x:Number($('#tech-x')?.value??t.dataset.x),y:Number($('#tech-y')?.value??t.dataset.y)});
  if(!POINTS[p.kind].net.includes(u.techNet))u.techNet=POINTS[p.kind].net[0];
  showTechnical();return true;
 }
 if(t.dataset.techVia){armTechnical({mode:'via',point:editedTechnicalPoint(t.dataset.techVia)});return true;}
 if(t.dataset.techAuto){action(()=>{delete s.technical.points.find(p=>p.id===t.dataset.techAuto).via[u.techNet];});showTechnical();return true;}
 if(t.dataset.techDelete){
  action(()=>{const p=s.technical.points.find(p=>p.id===t.dataset.techDelete);if(p.source)s.technical.excluded.push(p.source);s.technical.points=s.technical.points.filter(q=>q.id!==p.id);});
  showTechnical();toast('Point retiré');return true;
 }
 switch(t.dataset.techAction){
  case 'back':showTechnical();break;
  case 'view':$('#modal').close();renderPlan();break;
  case 'off':u.techNet=null;u.techPlacement=null;renderPlan();break;
  case 'cancel':u.techPlacement=null;renderPlan();break;
  case 'add':technicalPointDialog();break;
  case 'origin':armTechnical({mode:'origin'});break;
  case 'suggest':{
   const suggested=suggestPoints(s,u.levelId).slice(0,450-s.technical.points.length);
   if(suggested.length)action(()=>s.technical.points.push(...suggested));
   showTechnical();toast(suggested.length===0?'Tous les points proposés sont déjà traités':`${suggested.length} point${suggested.length===1?' proposé':'s proposés'} sur ce niveau`);break;
  }
  default:return false;
 }
 return true;
}
function placeTechnical(e){
 const task=u.techPlacement,p=point(e),building={x:0,y:0,...s.building};
 let xy={x:clamp(snap(p.x),0,building.w),y:clamp(snap(p.y),0,building.l)};
 if(task.wall){
  const room=s.rooms.find(r=>r.levelId===u.levelId&&xy.x>=r.x&&xy.x<=r.x+r.w&&xy.y>=r.y&&xy.y<=r.y+r.l);
  const wall=nearestWall(room||building,xy.x,xy.y);xy={x:wall.x,y:wall.y};
 }
 u.techPlacement=null;
 if(task.mode==='origin')action(()=>{(s.technical.origins[u.levelId]??={})[u.techNet]=xy;});
 if(task.mode==='point'){
  if(!POINTS[task.point.kind].net.includes(u.techNet))u.techNet=POINTS[task.point.kind].net[0];
  storeTechnicalPoint(task.point,xy);
 }
 if(task.mode==='via'){
  const original=s.technical.points.find(p=>p.id===task.point.id);
  storeTechnicalPoint({...task.point,via:{...task.point.via,[u.techNet]:xy}},{x:original.x,y:original.y});
 }
 toast(task.mode==='via'?'Passage enregistré':task.mode==='origin'?'Origine placée':'Point placé');
}
function renderTechnicalBar(){
 const on=u.view==='plan'&&u.techNet,placing=on&&u.techPlacement;
 $('#technical-bar').hidden=u.view!=='plan';
 $('#technical-button').setAttribute('aria-pressed',String(!!on));
 $('#tech-status').textContent=placing?{point:'Touchez pour placer le point',origin:'Touchez pour placer l’origine',via:'Touchez pour choisir le passage'}[placing.mode]:on?NETWORKS[u.techNet].name:'';
 $('#tech-close').hidden=!on;$('#tech-close').dataset.techAction=placing?'cancel':'off';
 $('#tech-close').textContent=placing?'Annuler':'Masquer';
 $('#board').classList.toggle('tech-placing',!!placing);
}
function versionsDialog(){
 save();
 const versions=projects[activeId].versions;
 openModal('Versions du plan',`<p>Créez un point de restauration avant de modifier votre plan. Les versions restent sur cet appareil et peuvent être incluses dans un export JSON.</p><label class="field"><span>Nom de la version</span><input id="version-name" maxlength="70" placeholder="Ex. Plan avant travaux"></label><div class="tech-actions"><button class="btn primary" data-version-new>Enregistrer une version</button><button class="btn" data-export="archive">Exporter avec l’historique</button></div>${versions.length?versions.map(v=>`<div class="tech-row"><strong>${esc(v.name)}</strong><small>${new Date(v.date).toLocaleString('fr-FR')}</small><div class="tech-actions"><button class="btn" data-version-restore="${esc(v.id)}">Restaurer</button><button class="btn" data-version-file="${esc(v.id)}">Exporter</button></div></div>`).join(''):'<p>Aucune version enregistrée pour ce plan.</p>'}<p class="tech-note">Les ${VERSION_LIMIT} dernières versions sont conservées.</p>`);
}
function savePlanVersion(name){
 const version=captureVersion(s,u.levelId,name);
 const project=projects[activeId];
 project.versions=[version,...(project.versions||[])].slice(0,VERSION_LIMIT);
 save();
}
function restorePlanVersion(id){
 const version=projects[activeId]?.versions.find(v=>v.id===id);
 if(!version)return;
 confirmAction('Restaurer cette version ?',`La version « ${esc(version.name)} » remplacera le plan ouvert. Une copie du plan actuel sera enregistrée dans l’historique.`,()=>{
  savePlanVersion('Avant restauration de '+version.name);
  action(()=>{s=normalize(version.data);u.levelId=version.levelId;u.selected=null;u.techPlacement=null;},true);
  toast('Version restaurée');
 });
}

function handleAction(a){if(a==='technical')showTechnical();if(a==='versions')versionsDialog();if(a==='add-level')newLevelDialog();if(a==='level-settings')go('building');if(a==='remove-level')removeLevel();if(a==='stairs')addStairs();if(a==='draw')beginDrawing();if(a==='apply-height')action(()=>{for(const r of s.rooms.filter(r=>r.levelId===u.levelId))r.h=activeLevel().height;});if(a==='rotate')rotate();if(a==='duplicate')duplicate();if(a==='delete')remove();if(a==='inspect'){renderInspector();$('.app').classList.remove('show-catalog');$('.app').classList.add('show-inspector');}if(a==='print')printProject();if(a==='import'){$('#popover').hidden=true;$('#import-file').click();}if(a==='projects'){$('#popover').hidden=true;projectsDialog();}if(a==='methods')methods();if(a==='overview'){openModal('Le bilan de votre projet',overview(compute(s))+thermalCard(compute(s)));}}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(t&&isMobile()){if(t.dataset.mobileStep){const input=t.closest('.field')?.querySelector('input[type=number]');if(input){const step=Number(input.step)||1,min=input.min===''?-Infinity:Number(input.min),max=input.max===''?Infinity:Number(input.max);input.value=Number(clamp((Number(input.value)||0)+step*Number(t.dataset.mobileStep),min,max).toFixed(6));markMobileDirty(input);}return;}flushMobileEdits();if(t.dataset.mobileNudge){nudgeMobile(t.dataset.mobileNudge);return;}if(t.dataset.mobileBrowse){u.mobileBrowse=t.dataset.mobileBrowse;u.mobileFind='';renderCatalog();return;}if(t.dataset.mobilePick){const [type,id]=t.dataset.mobilePick.split(':');u.tool='pan';choose(type,id);closeDrawers();mobileFocus();return;}if(t.dataset.mobile){mobileCommand(t.dataset.mobile);return;}if(t.dataset.mobileAdd){u.mobilePanel='add';u.query='';if(t.dataset.mobileAdd==='openings')u.step='openings';else{u.step='layout';u.category=t.dataset.mobileAdd;}u.selected=null;render();$('.app').classList.remove('show-inspector');$('.app').classList.add('show-catalog');renderMobileShell();return;}if(t.dataset.mobileTab){u.mobileEditTab=t.dataset.mobileTab;$$('[data-mobile-panel]').forEach(x=>x.hidden=x.dataset.mobilePanel!==u.mobileEditTab);$$('[data-mobile-tab]').forEach(x=>x.classList.toggle('active',x.dataset.mobileTab===u.mobileEditTab));return;}if(t.dataset.mobileLevel){setLevel(t.dataset.mobileLevel);$('#modal').close();closeDrawers();return;}if(t.dataset.mobileLayer){u.layer=t.dataset.mobileLayer;$('#modal').close();renderPlan();return;}if(t.dataset.action==='rotate'||t.dataset.action==='duplicate'||t.dataset.action==='delete'){if($('#modal').open)$('#modal').close();}}if(!t){if(!e.target.closest('#popover'))$('#popover').hidden=true;return;}if(!e.target.closest('#popover')&&t.id!=='export-button'&&t.id!=='layer-button')$('#popover').hidden=true;
if(technicalCommand(t))return;
if(t.hasAttribute('data-version-new')){const name=$('#version-name').value.trim()||'Version du '+new Date().toLocaleString('fr-FR');savePlanVersion(name);versionsDialog();toast(storageOK?'Version enregistrée':'Stockage saturé · exportez avec l’historique');return;}
if(t.dataset.versionRestore){restorePlanVersion(t.dataset.versionRestore);return;}
if(t.dataset.versionFile){const v=projects[activeId].versions.find(q=>q.id===t.dataset.versionFile);if(v)download(new Blob([JSON.stringify(packPlan(v.data,v.levelId,[]),null,2)],{type:'application/json'}),filename()+'-version.json');return;}
if(t.hasAttribute('data-close-drawer'))closeDrawers();if(t.hasAttribute('data-modal-close'))$('#modal').close();if(t.hasAttribute('data-confirm')){$('#modal').close();const fn=confirmation;confirmation=null;fn?.();}if(t.hasAttribute('data-rename')){const name=$('#rename-value').value.trim();if(name){action(()=>s.name=name);$('#modal').close();}}
if(t.hasAttribute('data-create-surface'))createSurface();if(t.dataset.addSurface)surfaceDialog(t.dataset.addSurface);if(t.hasAttribute('data-create-level'))createLevel();if(t.dataset.level)setLevel(t.dataset.level);if(t.dataset.step)go(t.dataset.step);if(t.dataset.go){$('#modal').close();go(t.dataset.go);}if(t.dataset.category){u.category=t.dataset.category;u.query='';renderCatalog();}if(t.dataset.comfort){u.comfort=t.dataset.comfort;u.layer=u.comfort;render();}if(t.dataset.addRoom)addRoom(t.dataset.addRoom);if(t.dataset.addObject)addObject(t.dataset.addObject);if(t.dataset.addOpening)addOpening(t.dataset.addOpening);if(t.dataset.select){const [type,id]=t.dataset.select.split(':');choose(type,id,true);}if(t.dataset.inspector){u.inspector=t.dataset.inspector;renderInspector();}if(t.dataset.view){u.view=t.dataset.view;u.tool=isMobile()?'pan':'select';u.draft=null;renderPlan(true);}if(t.dataset.tool){u.tool=t.dataset.tool;renderPlan();}if(t.dataset.action)handleAction(t.dataset.action);if(t.dataset.camera){volumeView?.setCamera(t.dataset.camera);$('#modal').close();}if(t.dataset.export)exportFile(t.dataset.export);
if(t.dataset.preset)confirmAction('Repartir de ce scénario ?',`Le scénario ${t.dataset.preset} m² remplacera le plan ouvert. Vous pourrez annuler cette modification.`,()=>{action(()=>{s=preset(Number(t.dataset.preset));u.levelId='ground';u.selected=null;},true);toast('Scénario chargé');});
if(t.dataset.layer){u.layer=t.dataset.layer;$('#popover').hidden=true;renderPlan();}if(t.dataset.projectLoad)switchProject(t.dataset.projectLoad);if(t.dataset.projectNew==='copy')newProject(true);if(t.dataset.projectNew==='new')openModal('Nouveau plan',`<label class="field"><span>Type de bâtiment</span><select id="new-building-kind">${Object.entries(BUILDING_TYPES).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><button class="btn primary full" data-plan-create>Créer le plan</button>`);if(t.hasAttribute('data-plan-create'))newProject();if(t.dataset.projectDelete){const id=t.dataset.projectDelete;confirmAction('Supprimer ce projet ?',`La variante « ${esc(projects[id]?.data.name||'')} » sera retirée de cet appareil.`,()=>{delete projects[id];save();projectsDialog();});}
switch(t.id){case 'add-level':newLevelDialog();break;case 'level-settings':go('building');break;case 'volume-overhead':{const next={open:'fixtures',fixtures:'closed',closed:'open'};u.overhead=next[u.overhead];renderPlan();break;}case 'volume-cutaway':u.cutaway=!u.cutaway;renderPlan();break;case 'volume-angle':openModal('Point de vue',`<div class="m-menu-list">${[['iso','cube','Perspective'],['top','plan','Vue de dessus'],['front','building','Vue de face']].map(([key,i,label])=>`<button data-camera="${key}"><span class="m-menu-icon">${icon(i)}</span><span><strong>${label}</strong></span></button>`).join('')}</div>`);break;case 'volume-isolate':u.allLevels=!u.allLevels;renderPlan(true);break;case 'volume-explode':u.exploded=!u.exploded;u.allLevels=true;renderPlan(true);break;case 'undo':undo();break;case 'redo':redo();break;case 'fit':case 'fit-top':case 'zoom-value':renderPlan(true);break;case 'zoom-in':zoom(1.25);break;case 'zoom-out':zoom(.8);break;case 'export-button':exportMenu();break;case 'projects-button':projectsDialog();break;case 'project-name':renameDialog();break;case 'help-button':case 'shortcuts-button':guide();break;case 'method-button':methods();break;case 'grid-toggle':u.grid=!u.grid;renderPlan();break;case 'snap-toggle':u.snap=!u.snap;renderPlan();toast(u.snap?'Aimantation activée · pas de 10 cm':'Placement libre');break;case 'fullscreen':$('.app').classList.toggle('fullscreen');break;case 'mobile-catalog':$('.app').classList.add('show-catalog');break;case 'layer-button':showPopover(t,[['layout','Aménagement','layout'],['light','Lumière & vitrage','sun'],['thermal','Enveloppe isolée','snow'],['ceiling','Plan des plafonds','layers']].map(([k,label,i])=>`<button data-layer="${k}" class="${u.layer===k?'active':''}">${icon(i)}${label}</button>`).join(''));break;}
});
$('#drawer-shade').addEventListener('click',closeDrawers);
document.addEventListener('input',e=>{markMobileDirty(e.target);if(e.target.id==='catalog-search'){u.query=e.target.value;$('#catalog-items').innerHTML=catalogItems();}if(e.target.id==='mobile-find'){u.mobileFind=e.target.value;$('#mobile-element-items').innerHTML=elementItems(s,u);}});
document.addEventListener('change',e=>{
 const el=e.target;
 if(el.dataset.shell){flushMobileEdits(false);action(()=>s.building[el.dataset.shell]=el.checked);return;}
 if(el.dataset.techPrice){
  action(()=>s.technical.prices[el.dataset.techPrice]=el.value);
  const estimate=technicalEstimate(s);$('#technical-estimate-total').textContent=euro(estimate.budget);
  for(const row of estimate.items){const total=$(`[data-tech-total="${row.key}"]`);if(total)total.textContent=euro(row.total);}
  return;
 }
 if(el.id==='tech-kind'){$('#tech-circuit-field').hidden=!POINTS[el.value].circuit;return;}
 if(isMobile()&&el.matches('[data-path],[data-entity-field],[data-level-field]')){markMobileDirty(el);return;}
 if(el.id==='surface-level'){$('#surface-altitude').hidden=el.value!=='new';return;}if(el.id==='new-level-kind'){$('#new-level-platform-fields').hidden=el.value!=='mezzanine';$('#new-level-name').value=el.value==='mezzanine'?'Mezzanine '+s.levels.length:'Étage '+s.levels.length;return;}
 if(el.id==='level-platform'){flushMobileEdits(false);action(()=>activeLevel().platform=el.checked?{x:0,y:0,w:Math.min(6,s.building.w),l:Math.min(4,s.building.l)}:null);return;}
 if(el.dataset.levelField){const path=el.dataset.levelField.split('.'),key=path.pop();action(()=>{const parent=path.reduce((o,k)=>o[k],activeLevel());parent[key]=key==='name'?el.value:Number(el.value);});return;}
 if(el.dataset.path){const path=el.dataset.path;action(()=>set(path,pathValue(path,el.value)));}
 if(el.dataset.entityField){const o=current();if(!o)return;const key=el.dataset.entityField,type=u.selected.type;
  action(()=>{
   if(key==='owner'){const room=el.value.startsWith('room:')?s.rooms.find(r=>r.id===el.value.slice(5)):null;o.host=room?'room':el.value;o.roomId=room?.id||null;if(room)o.levelId=room.levelId;o.offset=0;}
   else if(key==='roomId'){const pos=objectRect(s,o),r=s.rooms.find(r=>r.id===el.value);o.roomId=r?.id||null;o.x=pos.x-(r?.x||0);o.y=pos.y-(r?.y||0);if(r)o.levelId=r.levelId;}
   else if(key==='levelId'){if(type==='object'){const pos=objectRect(s,o);o.roomId=null;o.x=pos.x;o.y=pos.y;}if(type==='opening'&&o.host==='room'){o.host='building';o.roomId=null;}o.levelId=el.value;u.levelId=el.value;}
   else if(key==='railing')o.railing=el.value==='true';else o[key]=['name','type','wall','host','targetLevelId','finish','kind'].includes(key)?el.value||null:Number(el.value);
  });
 }
});

document.addEventListener('dragstart',e=>{const t=e.target.closest('[data-add-room],[data-add-object]');if(!t)return;e.dataTransfer.setData('text/plain',JSON.stringify({type:t.dataset.addRoom?'room':'object',kind:t.dataset.addRoom||t.dataset.addObject}));e.dataTransfer.effectAllowed='copy';});
$('#board').addEventListener('dragover',e=>{if(u.view==='plan'){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
$('#board').addEventListener('drop',e=>{e.preventDefault();try{const d=JSON.parse(e.dataTransfer.getData('text/plain')),p=point(e);if(d.type==='room')addRoom(d.kind,p);if(d.type==='object')addObject(d.kind,p);}catch(_){toast('Choisissez un élément dans le catalogue.');}});
function point(e){const svg=$('#plan'),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const m=svg.getScreenCTM();if(!m)return{x:0,y:0};return p.matrixTransform(m.inverse());}
const board=$('#board'),activeTouches=new Map();let pinch=null,techPress=null;
board.addEventListener('pointerdown',e=>{
 if(u.view!=='plan'||!u.techNet||e.button!==0||e.target.closest('button'))return;
 const marker=e.target.closest('[data-tech-point]');
 if(!u.techPlacement&&!marker)return;
 e.stopImmediatePropagation();
 techPress={id:e.pointerId,x:e.clientX,y:e.clientY,marker:marker?.dataset.techPoint};
},true);
board.addEventListener('pointerup',e=>{
 if(techPress?.id!==e.pointerId)return;
 e.stopImmediatePropagation();
 const press=techPress;techPress=null;
 if(Math.hypot(e.clientX-press.x,e.clientY-press.y)>12)return;
 if(u.techPlacement)placeTechnical(e);
 else if(press.marker)technicalPointDialog(press.marker);
},true);
board.addEventListener('pointercancel',e=>{if(techPress?.id===e.pointerId)techPress=null;},true);
board.addEventListener('pointerdown',e=>{
 if(u.view==='volume'&&volumeView)return;if(e.target.closest('button')||e.button>0&&e.pointerType!=='touch')return;
 if(isMobile()){
  activeTouches.set(e.pointerId,{clientX:e.clientX,clientY:e.clientY});board.setPointerCapture(e.pointerId);
  if(activeTouches.size>=2){
   if(drag&&drag.mode!=='pan'&&drag.mode!=='orbit')s=JSON.parse(drag.before);if(raf){cancelAnimationFrame(raf);raf=0;}
   const [a,b]=[...activeTouches.values()],center={clientX:(a.clientX+b.clientX)/2,clientY:(a.clientY+b.clientY)/2};
   pinch={distance:Math.max(1,Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY)),zoom:u.zoom,anchor:point(center),bounds:{...baseBounds}};drag=null;u.draft=null;board.classList.remove('dragging');renderPlan();e.preventDefault();return;
  }
 }else if(!e.isPrimary)return;
 const p=point(e),hit=e.target.closest('[data-entity]'),handle=e.target.closest('[data-handle]'),candidate=hit?{type:hit.dataset.entity,id:hit.dataset.id}:null;
 let mode=u.view==='volume'?'orbit':u.tool==='draw'?'draw':u.tool==='select'&&(handle||hit&&(!isMobile()||u.selected?.id===hit.dataset.id))?handle?'resize':'move':'pan';
 if(!isMobile()){if(hit&&u.tool==='select'){u.selected=candidate;u.inspector='selection';}else if(!handle&&mode==='pan'&&u.tool==='select')u.selected=null;}
 if(mode==='draw'){u.selected=null;u.draft=null;}
 const o=current();drag={mode,hit:candidate,start:{x:mode==='draw'?clamp(snap(p.x),0,s.building.w):p.x,y:mode==='draw'?clamp(snap(p.y),0,s.building.l):p.y,clientX:e.clientX,clientY:e.clientY},orig:o?structuredClone(o):null,absolute:o&&u.selected.type==='object'?objectRect(s,o):null,before:JSON.stringify(s),panX:u.panX,panY:u.panY,yaw:u.yaw,moved:false};board.setPointerCapture(e.pointerId);e.preventDefault();renderPlan();renderInspector();
});
board.addEventListener('pointermove',e=>{
 if(activeTouches.has(e.pointerId))activeTouches.set(e.pointerId,{clientX:e.clientX,clientY:e.clientY});
 if(pinch&&activeTouches.size>=2){const [a,b]=[...activeTouches.values()],r=board.getBoundingClientRect(),center={x:(a.clientX+b.clientX)/2-r.left,y:(a.clientY+b.clientY)/2-r.top};Object.assign(u,pinchView({bounds:pinch.bounds,zoom:pinch.zoom*Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY)/pinch.distance,anchor:pinch.anchor,center,viewport:{width:r.width,height:r.height}}));applyViewBox();e.preventDefault();return;}
 if(!drag)return;const dxpx=e.clientX-drag.start.clientX,dypx=e.clientY-drag.start.clientY;if(Math.hypot(dxpx,dypx)>(isMobile()?8:3))drag.moved=true;if(!drag.moved)return;board.classList.add('dragging');
 if(drag.mode==='orbit'){u.yaw=drag.yaw+dxpx*.35;renderPlan();return;}
 if(drag.mode==='pan'){const m=$('#plan').getScreenCTM();u.panX=drag.panX-dxpx/m.a;u.panY=drag.panY-dypx/m.d;applyViewBox();return;}
 const p=point(e);
 if(drag.mode==='draw'){const x=clamp(snap(p.x),0,s.building.w),y=clamp(snap(p.y),0,s.building.l);u.draft={x:Math.min(drag.start.x,x),y:Math.min(drag.start.y,y),w:Math.abs(x-drag.start.x),l:Math.abs(y-drag.start.y)};renderPlan();return;}
 const dx=snap(p.x-drag.start.x),dy=snap(p.y-drag.start.y),o=current(),q=drag.orig;if(!o||!q)return;const type=u.selected.type;
 if(drag.mode==='resize'&&type==='surface'){const b=surfaceLimits(s,o);o.w=clamp(snap(q.w+dx),.6,b.maxW);o.l=clamp(snap(q.l+dy),.6,b.maxL);}
 else if(drag.mode==='resize'){const parent=type==='object'&&o.roomId?s.rooms.find(r=>r.id===o.roomId):s.building,min=type==='object'?.15:.6;o.w=clamp(snap(q.w+dx),min,parent.w-q.x);o.l=clamp(snap(q.l+dy),min,parent.l-q.y);}
 else if(type==='opening'){const parent=openingParent(s,o),len=['north','south'].includes(o.wall)?parent.w||s.building.w:parent.l||s.building.l;o.offset=clamp(snap(q.offset+(['north','south'].includes(o.wall)?dx:dy)),0,len-o.w);}
 else if(type==='object'){const x=clamp(snap(drag.absolute.x+dx),0,s.building.w-o.w),y=clamp(snap(drag.absolute.y+dy),0,s.building.l-o.l),lid=objectLevel(s,o),r=o.kind==='stairs'||OBJECTS[o.kind].group==='pool'?null:s.rooms.find(r=>r.levelId===lid&&x+o.w/2>=r.x&&x+o.w/2<=r.x+r.w&&y+o.l/2>=r.y&&y+o.l/2<=r.y+r.l&&o.w<=r.w&&o.l<=r.l);o.roomId=r?.id||null;o.levelId=lid;o.x=clamp(x-(r?.x||0),0,(r||s.building).w-o.w);o.y=clamp(y-(r?.y||0),0,(r||s.building).l-o.l);}
 else if(type==='surface'){const b=surfaceLimits(s,o);o.x=clamp(snap(q.x+dx),b.minX,b.maxX);o.y=clamp(snap(q.y+dy),b.minY,b.maxY);}
 else{o.x=clamp(snap(q.x+dx),0,s.building.w-o.w);o.y=clamp(snap(q.y+dy),0,s.building.l-o.l);}
 if(!raf)raf=requestAnimationFrame(()=>{raf=0;renderPlan();renderMetrics();});e.preventDefault();
});
function finishDrag(){
 if(!drag)return;const d=drag;drag=null;board.classList.remove('dragging');if(raf){cancelAnimationFrame(raf);raf=0;}
 if(d.mode==='draw'){const q=u.draft;u.draft=null;u.tool=isMobile()?'pan':'select';if(q&&q.w>=.6&&q.l>=.6)addRoom(u.drawType,null,q);else{renderPlan();toast('Tracez une pièce d’au moins 60 cm de côté.');}return;}
 if(isMobile()&&!d.moved){if(d.hit){if(u.selected?.id!==d.hit.id)u.tool='pan';choose(d.hit.type,d.hit.id);}else{u.selected=null;u.tool='pan';renderPlan();renderInspector();}return;}
 if(d.mode!=='pan'&&d.mode!=='orbit'&&d.moved){s=normalize(s);if(d.before!==JSON.stringify(s)){past.push(d.before);future=[];save();}if(isMobile()&&d.mode==='resize'){u.tool='pan';u.mobileResize=false;}render();}else{renderPlan();renderInspector();}
}
board.addEventListener('pointerup',e=>{
 activeTouches.delete(e.pointerId);
 if(pinch){pinch=null;const left=[...activeTouches.values()][0];if(left){const p=point(left);drag={mode:'pan',hit:null,start:{x:p.x,y:p.y,...left},orig:null,absolute:null,before:JSON.stringify(s),panX:u.panX,panY:u.panY,yaw:u.yaw,moved:true};}else drag=null;renderPlan();return;}
 finishDrag();
});
board.addEventListener('pointercancel',()=>{if(drag&&drag.mode!=='orbit'&&drag.mode!=='pan')s=JSON.parse(drag.before);drag=null;pinch=null;activeTouches.clear();u.draft=null;board.classList.remove('dragging');render();});
board.addEventListener('dblclick',e=>{if(u.view==='volume'&&volumeView)return;if(e.target.closest('button'))return;if(isMobile()){const hit=e.target.closest('[data-entity]');if(hit){choose(hit.dataset.entity,hit.dataset.id);mobileFocus();}else renderPlan(true);e.preventDefault();}});
board.addEventListener('contextmenu',e=>{if(isMobile())e.preventDefault();});

board.addEventListener('wheel',e=>{if(u.view==='volume'&&volumeView)return;e.preventDefault();zoom(e.deltaY<0?1.08:1/1.08,e);},{passive:false});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>20e6)throw Error('Ce fichier est trop volumineux (maximum 20 Mo).');const loaded=unpackPlan(JSON.parse(await f.text()));save();activeId=uid();projects[activeId]={versions:loaded.versions};s=loaded.data;past=[];future=[];u.levelId=loaded.levelId;u.selected=null;u.techPlacement=null;save();render(true);$('#modal').close();closeDrawers();toast(storageOK?'Plan importé dans un nouveau projet':'Plan ouvert · stockage de cet appareil saturé');}catch(err){toast('Import impossible : '+err.message);}e.target.value='';});
document.addEventListener('keydown',e=>{const input=/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable;if($('#modal').open){if(e.key==='Enter'&&$('#rename-value')){e.preventDefault();$('[data-rename]').click();}return;}if(input)return;const ctrl=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(ctrl&&k==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(ctrl&&k==='y'){e.preventDefault();redo();return;}if(ctrl&&k==='d'){e.preventDefault();duplicate();return;}if(e.key==='Escape'){closeDrawers();$('.app').classList.remove('fullscreen');if(drag){s=JSON.parse(drag.before);drag=null;}u.draft=null;u.tool='select';u.selected=null;$('#popover').hidden=true;render();}if(k==='n')beginDrawing();if(k==='r')rotate();if(k==='v'){u.tool='select';renderPlan();}if(k==='h'){u.tool='pan';renderPlan();}if(k==='0')renderPlan(true);if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}if(k==='?')guide();if(e.key.startsWith('Arrow')&&current()&&u.selected.type!=='opening'){e.preventDefault();const d=e.shiftKey?1:.1,o=current();action(()=>{if(e.key==='ArrowLeft')o.x-=d;if(e.key==='ArrowRight')o.x+=d;if(e.key==='ArrowUp')o.y-=d;if(e.key==='ArrowDown')o.y+=d;});}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
setupMobile();save();render(true);
